update public.hero_messages set text = 'Quem sentir que falta clareza numa decisão difícil pode simplesmente pedir — foi escrito pra gente no meio de provas reais, não pra uma pergunta teórica.' where slug = 'peca-sabedoria-com-fe';
update public.hero_messages set text = '"Enxugará dos olhos deles toda lágrima, e não haverá mais morte" é a última cena de um dos relatos mais estranhos já escritos — termina em restauração, não em juízo.' where slug = 'nenhuma-lagrima-restaurada';
update public.hero_messages set text = 'Fugindo de casa sozinho e sem nada, ele dormiu numa pedra e sonhou com uma escada até o céu — o lugar mais desamparado virou onde algo maior se revelou.' where slug = 'escada-de-jaco';
update public.hero_messages set text = 'Prometeram um filho a um homem de noventa anos. Ele riu — e o filho ainda assim chegou. Rir de descrença não cancela a promessa.' where slug = 'sara-riu-da-promessa';
update public.hero_messages set text = 'Um homem quase não mencionado em toda essa história antiga pediu, numa única oração curta, para ser abençoado além dos próprios limites — e recebeu exatamente isso.' where slug = 'oracao-de-jabes';
update public.hero_messages set text = 'Sedento como um cervo procurando água num terreno seco, o autor confessa que sua alma tem sede de algo maior em meio às próprias lágrimas dia e noite.' where slug = 'como-a-corca-anseia';
update public.hero_messages set text = 'Ele pediu dois sinais antes de acreditar que era mesmo chamado pra a missão. Ninguém se ofendeu com a dúvida — vieram as duas respostas.' where slug = 'gideao-pediu-dois-sinais';
update public.hero_messages set text = 'Um convite curto e direto: entre com alegria, cante, reconheça a quem tudo pertence, e agradeça — sem complicação nenhuma no meio do caminho.' where slug = 'entrai-com-accao-de-gracas';
update public.hero_messages set text = 'Vestido de peles, comendo gafanhotos no deserto, ele atraía multidões pregando arrependimento — e quando o homem que ele mesmo anunciava finalmente apareceu, disse que não era digno nem de servi-lo.' where slug = 'joao-batista-preparava-o-caminho';
update public.hero_messages set text = 'Enquanto ricos depositavam grandes somas visivelmente, uma viúva colocou duas moedinhas de pouquíssimo valor — e foi ela quem um observador silencioso apontou como quem mais tinha dado.' where slug = 'duas-moedinhas-da-viuva';
update public.hero_messages set text = 'Mandaram ele ficar quieto, mas quanto mais tentavam calá-lo, mais alto ele gritava — e foi esse grito insistente que fez o homem que passava parar no meio da multidão.' where slug = 'bartimeu-gritou-mais-alto';
update public.hero_messages set text = 'Grávida, ainda adolescente, numa situação socialmente arriscada, ela respondeu com um cântico sobre uma força maior que derruba poderosos e exalta os humildes.' where slug = 'magnificat-de-maria';
update public.hero_messages set text = 'Ela voltava repetidamente pedindo justiça a um juiz que não temia nada nem se importava com ninguém — e foi só de tanto insistir que ele finalmente cedeu.' where slug = 'viuva-insistente';
update public.hero_messages set text = 'Um líder religioso respeitado foi conversar com ele escondido, de noite, com medo do que os outros pensariam — e ouviu que precisava nascer de novo pra realmente entender.' where slug = 'nicodemos-nascer-de-novo';
update public.hero_messages set text = 'Quando disseram que ele nem tinha idade suficiente para ter visto Abraão, a resposta usou o mesmo nome usado séculos antes numa sarça que pegava fogo sem se consumir.' where slug = 'antes-de-abraao-eu-sou';
update public.hero_messages set text = 'Um oficial romano, gentio, devoto mas fora da aliança judaica, recebeu uma visão pedindo que chamasse um pescador — e essa visita quebrou uma barreira que ninguém esperava ver quebrada.' where slug = 'visao-de-cornelio';
update public.hero_messages set text = 'Uma comerciante de púrpura, já devota, estava simplesmente orando à beira de um rio quando ouviu um viajante pregar — e o relato diz que foi algo além dela mesma que abriu seu coração pra prestar atenção.' where slug = 'lidia-abriu-o-coracao';
update public.hero_messages set text = 'No meio de uma lista de leis sobre colheita, honestidade e justiça, um mandamento resume todos os outros — e continuaria sendo citado séculos depois.' where slug = 'amaras-o-teu-proximo';
update public.hero_messages set text = 'Antes de qualquer lista de regras, vem uma declaração sobre a quem tudo pertence — e só depois vem a instrução de ensinar isso aos filhos em toda hora do dia.' where slug = 'ouve-israel-o-shema';
update public.hero_messages set text = '"Vestir uma armadura invisível" foi escrito por alguém preso numa cela, comparando fé a proteção de soldado. Nem toda batalha é visível de fora.' where slug = 'armadura-escrita-da-prisao';
update public.hero_messages set text = 'Um profeta foi instruído a se casar com uma mulher que sabia que o trairia repetidamente — pra que sua própria vida virasse ilustração viva do que era amar alguém infiel.' where slug = 'oseias-e-gomer';
update public.hero_messages set text = 'Depois de anos de construção, no dia da inauguração, o próprio rei que mandou construir se ajoelhou em público e admitiu que nenhuma casa seria grande o bastante para conter aquilo que ali seria adorado.' where slug = 'dedicacao-do-templo';
update public.hero_messages set text = 'No começo era só vazio e escuro. Ninguém corrigiu o caos — criou luz dentro dele.' where slug = 'criacao-da-luz';
update public.hero_messages set text = 'Antes de seguir pra próxima etapa, alguém parou, olhou pro que tinha feito e chamou de bom. Você pode fazer o mesmo hoje.' where slug = 'deus-viu-que-era-bom';
update public.hero_messages set text = 'Os dois primeiros se esconderam depois do erro. Foram atrás deles mesmo assim — a primeira pergunta de toda essa história é "onde você está", não "o que você fez".' where slug = 'onde-voce-esta';
update public.hero_messages set text = 'Depois do dilúvio, o primeiro sinal no céu não foi um aviso — foi uma promessa. Alguém sempre lembra de recomeçar.' where slug = 'arco-iris-promessa';
update public.hero_messages set text = 'Ela foi expulsa pro deserto e achou que ninguém mais a via. Alguém a chamou pelo nome exatamente ali.' where slug = 'agar-vista-no-deserto';
update public.hero_messages set text = 'Ele foi vendido pelos próprios irmãos e ainda assim escolheu não virar amargura. "Vocês pensaram o mal, isso voltou em bem" não é ingenuidade, é memória longa.' where slug = 'jose-vendido-pelos-irmaos';
update public.hero_messages set text = 'No Egito, ele interpretou sonhos de um rei que nem compartilhava da sua fé. Dom não escolhe plateia.' where slug = 'jose-interpreta-sonhos';
update public.hero_messages set text = 'Uma sarça pegava fogo e não se consumia. Chamados importantes vêm de dentro de coisas simples.' where slug = 'sarca-ardente';
update public.hero_messages set text = 'Ele disse que não sabia falar direito. Ninguém trocou o mensageiro — deram um irmão pra ajudar.' where slug = 'moises-nao-sabia-falar';
update public.hero_messages set text = 'Enquanto o líder demorava no monte, o povo fundiu ouro num bezerro. Impaciência costuma criar ídolos pequenos.' where slug = 'bezerro-de-ouro';
update public.hero_messages set text = 'Ele pediu pra ver a glória plena e só pôde ver as costas dela passando. Nem toda pergunta recebe a resposta completa — e está tudo bem.' where slug = 'moises-viu-as-costas-de-deus';
update public.hero_messages set text = 'Reduziram o exército dele de milhares pra trezentos antes da batalha. Quando dá pra explicar a vitória pela força humana, ainda não é hora de vencer.' where slug = 'exercito-reduzido-a-trezentos';
update public.hero_messages set text = 'Ele era o mais novo, o esquecido na hora de chamar pra reunião — e foi o escolhido. Alguém sempre olha pro que os outros nem reparam.' where slug = 'davi-o-esquecido-escolhido';
update public.hero_messages set text = 'Não estava no vento forte, nem no terremoto, nem no fogo. Estava num sussurro. Nem sempre a resposta chega do jeito espalhafatoso que a gente espera.' where slug = 'deus-no-sussurro';
update public.hero_messages set text = 'Ele perdeu quase tudo e ainda assim recusou trocar sinceridade por respostas fáceis. Ter raiva em voz alta é diferente de desistir de vez.' where slug = 'jo-recusou-respostas-faceis';
update public.hero_messages set text = 'No fim, ele não recebeu uma explicação completa pro sofrimento — recebeu uma presença. Às vezes isso é o suficiente, mesmo sem entender tudo.' where slug = 'jo-recebeu-presenca-nao-explicacao';
update public.hero_messages set text = 'Ele reclamou de ser jovem demais pro chamado. A resposta foi que já o conheciam antes de ele nascer — idade nunca foi o requisito.' where slug = 'jeremias-jovem-demais';
update public.hero_messages set text = 'Um profeta comparou essa força maior a um oleiro remodelando um vaso que deu errado — não descartando, remodelando.' where slug = 'oleiro-remodela-o-vaso';
update public.hero_messages set text = 'Três homens disseram que podiam ser livrados da fornalha — e que, mesmo se não fossem, não iam ceder. Fé não é garantia de resultado, é decisão de lealdade.' where slug = 'fornalha-mesmo-se-nao-livrar';
update public.hero_messages set text = 'Ele passou a noite na cova dos leões e a primeira coisa que disse de manhã foi que algo tinha fechado a boca deles. Proteção às vezes é silenciosa até o dia clarear.' where slug = 'daniel-cova-dos-leoes';
update public.hero_messages set text = 'Ele fugiu na direção contrária do chamado e ainda assim a história não terminou aí. Algumas coisas perseguem quem foge, não só quem obedece.' where slug = 'jonas-fugiu-na-direcao-contraria';
update public.hero_messages set text = 'Ele nasceu numa cidade pequena, numa noite comum, num lugar sem conforto nenhum. Coisas grandes nem sempre começam parecendo grandes.' where slug = 'jesus-nasceu-em-lugar-comum';
update public.hero_messages set text = 'Antes de começar qualquer coisa em público, ele passou quarenta dias sozinho no deserto sendo testado. Preparo real às vezes acontece longe de plateia.' where slug = 'quarenta-dias-antes-de-comecar';
update public.hero_messages set text = 'Ele chamou pescadores no meio do trabalho comum, não em nenhum momento espiritual especial. Chamado interrompe rotina, não substitui ela.' where slug = 'jesus-chamou-no-meio-do-trabalho';
update public.hero_messages set text = 'Um paralítico foi baixado pelo teto por amigos que não desistiram de achar um jeito de chegar até ele. Às vezes a fé de alguém carrega a de outro.' where slug = 'amigos-desceram-pelo-teto';
update public.hero_messages set text = 'A mulher no poço foi encontrada no horário em que evitava todo mundo. Ele escolheu justamente aquele horário pra estar lá.' where slug = 'mulher-no-poco-no-horario-certo';
update public.hero_messages set text = 'No meio da tempestade, o grupo gritou de medo enquanto ele dormia. A pergunta dele não foi sobre a tempestade — foi sobre a fé deles.' where slug = 'tempestade-acalmada';
update public.hero_messages set text = 'Ele andou sobre a água enquanto olhava pra frente, e afundou no instante em que olhou pro vento. A queda começou na virada do olhar.' where slug = 'pedro-afundou-olhando-o-vento';
update public.hero_messages set text = 'Ele subiu numa árvore só pra conseguir ver, sem esperar ser visto de volta. O homem parou embaixo justamente daquela árvore.' where slug = 'zaqueu-subiu-so-para-ver';
update public.hero_messages set text = 'Ela reclamou que a irmã não ajudava na cozinha enquanto a outra só ouvia. A resposta foi que ela tinha escolhido a melhor parte — nem toda ajuda é a coisa certa a fazer agora.' where slug = 'marta-maria-melhor-parte';
update public.hero_messages set text = 'Ele já estava morto havia quatro dias quando o amigo chegou de propósito atrasado. Demora não é a mesma coisa que ausência.' where slug = 'lazaro-atraso-proposital';
update public.hero_messages set text = 'Ele chorou diante do túmulo do amigo mesmo sabendo o que ia fazer em seguida. Esperança não cancela a permissão de sentir dor.' where slug = 'jesus-chorou-mesmo-sabendo';
update public.hero_messages set text = 'Na última ceia, ele lavou os pés de todos ali — inclusive o de quem ia traí-lo naquela mesma noite. Serviço não escolhe quem merece.' where slug = 'lavou-os-pes-de-quem-o-trairia';
update public.hero_messages set text = 'No jardim, ele pediu pra que aquele momento passasse dele, e ainda assim disse "não seja como eu quero". Obediência não exige fingir que é fácil.' where slug = 'nao-seja-como-eu-quero';
update public.hero_messages set text = 'Ele jurou que nunca negaria o amigo e negou três vezes antes do galo cantar. A queda mais dura costuma vir logo depois da certeza mais forte.' where slug = 'pedro-negou-tres-vezes';
update public.hero_messages set text = 'Depois de tudo, a primeira pergunta pra ele não foi sobre a negação — foi "você me ama?", repetida três vezes. Restauração apaga a dívida, não a memória.' where slug = 'voce-me-ama-tres-vezes';
update public.hero_messages set text = 'Dois amigos caminharam horas ao lado de alguém sem reconhecê-lo, até o pão ser partido. Às vezes a resposta está bem perto e ainda assim invisível até o momento certo.' where slug = 'emaus-reconhecido-no-pao';
update public.hero_messages set text = 'Ele disse que só acreditaria vendo as marcas com os próprios olhos. O visitante voltou só pra ele ver — dúvida sincera não fecha a porta.' where slug = 'tome-a-duvida-sincera';
update public.hero_messages set text = 'Disseram que odiavam as festas religiosas deles — não porque adoração fosse ruim, mas porque vinha misturada com injustiça que ninguém corrigia.' where slug = 'justica-como-agua-corrente';
update public.hero_messages set text = 'Depois de perguntar com que sacrifício grande poderia agradar quem tudo vê, a resposta foi surpreendentemente simples: praticar a justiça, amar a misericórdia, andar humildemente.' where slug = 'o-que-o-senhor-pede';
update public.hero_messages set text = 'A imagem não é de alguém distante avaliando de longe — é de uma presença no meio do povo, se alegrando tanto a ponto de cantar de alegria por quem ama.' where slug = 'ele-se-alegra-com-cantos';
update public.hero_messages set text = 'A definição não foi "ele tem amor" ou "ele demonstra amor" — foi mais direta: "ele é amor", como se os dois fossem, de alguma forma, a mesma coisa.' where slug = 'deus-e-amor';
update public.hero_messages set text = 'Um convite pra um debate é feito ao povo — não pra condená-los mais, mas pra argumentar a favor da própria limpeza que está sendo oferecida.' where slug = 'ainda-que-os-vossos-pecados';
update public.hero_messages set text = 'No meio de um dos lamentos mais tristes já escritos, sobre os escombros de uma cidade destruída, aparece a frase que décadas depois viraria um dos hinos mais cantados da história.' where slug = 'misericordias-do-senhor-cada-manha';
update public.hero_messages set text = 'Uma praga de gafanhotos havia devorado anos de colheita — e a promessa que veio a seguir não foi apenas parar a praga, foi devolver o tempo que ela consumiu.' where slug = 'restituirei-os-anos-do-gafanhoto';
update public.hero_messages set text = 'A promessa não é que tudo que acontece seja bom — é que nada fica de fora de uma soma final que caminha para o bem de quem confia.' where slug = 'todas-as-coisas-contribuem-para-o-bem';